import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"Documentation Map","description":"The single documentation source, directory structure, reading hierarchy, bilingual rules, and update workflow for Hearth.","frontmatter":{"title":"Documentation Map","description":"The single documentation source, directory structure, reading hierarchy, bilingual rules, and update workflow for Hearth.","outline":[2,3]},"headers":[],"relativePath":"en/reference/source-map.md","filePath":"en/reference/source-map.md","lastUpdated":1793797632000}'),n={name:"en/reference/source-map.md"};function o(l,e,s,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<p class="eyebrow">DOCUMENTATION MAP</p><h1 id="documentation-map" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h1><p class="lead">All formal documentation lives only in <code>docs/</code>. The site is built directly from that folder, and the README files are repository entry points, so the repository and the published site always use the same documentation.</p><h2 id="documentation-map-1" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map-1" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Content</th><th>Entry</th></tr></thead><tbody><tr><td>Design</td><td>Positioning, principles, tradeoffs, architecture, and current status</td><td><a href="/hearth-os/en/design/">Design</a></td></tr><tr><td>Architecture</td><td>Protocols, control plane, executors, safety, memory, and evaluation</td><td><a href="/hearth-os/en/architecture/overview.html">Architecture Overview</a></td></tr><tr><td>Delivery</td><td>Six phases, 24 small stages, and the MVP</td><td><a href="/hearth-os/en/delivery/">Delivery Route</a></td></tr><tr><td>Development Log</td><td>One daily summary plus commits, concrete changes, and authors</td><td><a href="/hearth-os/en/log/day-02.html">Day02</a></td></tr><tr><td>Appendix</td><td>Engineering, risks, decisions, glossary, checklists, and archives</td><td><a href="/hearth-os/en/reference/">Appendix</a></td></tr></tbody></table><h2 id="reading-hierarchy" tabindex="-1">Reading Hierarchy <a class="header-anchor" href="#reading-hierarchy" aria-label="Permalink to &quot;Reading Hierarchy&quot;">​</a></h2><ol><li><strong>Design</strong> explains why the project exists, where its boundaries are, and which tradeoffs matter.</li><li><strong>Delivery Route overview</strong> explains the order, goals, and relationships of the six phases.</li><li><strong>Phase plans</strong> explain what a large phase must complete and why these things come first.</li><li><strong>Small-stage plans</strong> explain the concrete goal, implementation steps, and how completion is judged.</li></ol><p>Confirm the current phase&#39;s scope and goal before opening a concrete small-stage page; never infer the whole product scope from a single small stage.</p><h2 id="three-reading-paths" tabindex="-1">Three Reading Paths <a class="header-anchor" href="#three-reading-paths" aria-label="Permalink to &quot;Three Reading Paths&quot;">​</a></h2><h3 id="understand-the-product-and-design" tabindex="-1">Understand the Product and Design <a class="header-anchor" href="#understand-the-product-and-design" aria-label="Permalink to &quot;Understand the Product and Design&quot;">​</a></h3><ol><li><a href="/hearth-os/en/design/">Design and Tradeoffs</a></li><li><a href="/hearth-os/en/architecture/overview.html">Architecture and Data Flow</a></li><li><a href="/hearth-os/en/architecture/domain-model.html">Domain Model and Protocols</a></li><li><a href="/hearth-os/en/architecture/execution-safety.html">Execution Safety</a></li><li><a href="/hearth-os/en/architecture/evaluation.html">Evaluation</a></li></ol><h3 id="review-the-delivery-plan" tabindex="-1">Review the Delivery Plan <a class="header-anchor" href="#review-the-delivery-plan" aria-label="Permalink to &quot;Review the Delivery Plan&quot;">​</a></h3><ol><li><a href="/hearth-os/en/delivery/">Delivery Route and Implementation Plan</a></li><li><a href="/hearth-os/en/delivery/stage-1.html">Phase 1 · Minimum Complete MVP</a></li><li><a href="/hearth-os/en/delivery/stage-1/1-1.html">1.1 Define the first scenario and real tasks</a></li></ol><h3 id="start-building" tabindex="-1">Start Building <a class="header-anchor" href="#start-building" aria-label="Permalink to &quot;Start Building&quot;">​</a></h3><ol><li><a href="/hearth-os/en/delivery/stage-1.html">Phase 1 · Minimum Complete MVP</a></li><li><a href="/hearth-os/en/delivery/stage-1/1-1.html">1.1 Define the first scenario and real tasks</a></li><li><a href="/hearth-os/en/reference/engineering.html">Engineering and Repository Layout</a></li><li><a href="/hearth-os/en/reference/risks.html">Risks and Kill Criteria</a></li></ol><h2 id="documentation-hierarchy" tabindex="-1">Documentation Hierarchy <a class="header-anchor" href="#documentation-hierarchy" aria-label="Permalink to &quot;Documentation Hierarchy&quot;">​</a></h2><ul><li>Topic pages are the normal path for reading and maintenance, organized into design, delivery, log, and appendix.</li><li>Delivery has one structure only: overview, large phase plans, and small-stage plans; there is no parallel long-form archive.</li><li>When facts, protocols, or phase goals change, update the Chinese page, the English mirror, and related entry points together.</li></ul><h2 id="maintenance-workflow" tabindex="-1">Maintenance Workflow <a class="header-anchor" href="#maintenance-workflow" aria-label="Permalink to &quot;Maintenance Workflow&quot;">​</a></h2><ol><li>Edit the Chinese page first, confirming that conclusions, boundaries, and links remain accurate.</li><li>Create or update the English mirror at the same relative path under <code>docs/en/</code>.</li><li>Update related entry points, sidebars, and cross-links so no stale path remains.</li><li>Run <code>npm run docs:build</code> and eliminate build errors and internal dead links.</li><li>Check long tables, code blocks, mobile widths, and language switching in local preview.</li></ol><h2 id="pre-commit-checklist" tabindex="-1">Pre-Commit Checklist <a class="header-anchor" href="#pre-commit-checklist" aria-label="Permalink to &quot;Pre-Commit Checklist&quot;">​</a></h2><ul><li>Modify formal documentation only under <code>docs/</code>; do not add a second documentation root.</li><li>Keep Chinese and English paths aligned with matching heading levels and list counts.</li><li>Preserve the hierarchy: overview → large phase → small stage.</li><li>Keep README limited to the project pitch, quick start, and documentation navigation; do not duplicate long-form body text.</li><li>Keep one daily overview and a commit table in development logs; do not restore a log index or template.</li><li>Do not commit <code>docs/.vitepress/dist</code>, caches, local secrets, or completion claims without evidence.</li></ul><h2 id="documentation-and-release-boundary" tabindex="-1">Documentation and Release Boundary <a class="header-anchor" href="#documentation-and-release-boundary" aria-label="Permalink to &quot;Documentation and Release Boundary&quot;">​</a></h2><ul><li>The current documentation describes specifications, design judgments, and development plans; it does not mean the product has shipped.</li><li>Development logs record a daily overview, commits, specific changes, and authors; they never impersonate product release notes.</li><li>Maintain a formal version number and release notes only after implementation begins and an installable release exists.</li></ul>',23)])])}const p=a(n,[["render",o]]);export{m as __pageData,p as default};
